import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))

    points = []
    for _ in range(n):
        x = int(next(iterator))
        y = int(next(iterator))
        points.append((x, y))

    xs = sorted(set(p[0] for p in points))
    ys = sorted(set(p[1] for p in points))

    grid = set(points)

    for x in xs:
        for y in ys:
            if (x, y) not in grid:
                grid.add((x, y))

    result = list(grid)
    print(len(result))
    for x, y in result:
        print(x, y)

if __name__ == "__main__":
    main()
